entries[382033] = { ["name"] = "Wogende Schilde", ["text"] = "Elementar\nErhöht den von 'Blitzschlagschild' verursachten Schaden um 100% und bewirkt, dass beim Auslösen zusätzlich 4 Mahlstrom erzeugt werden.\n\nErhöht die von 'Erdschild' hervorgerufene Heilung um 25%.\n\nVerstärkung\nErhöht den von 'Blitzschlagschild' verursachten Schaden um 100%. Außerdem wird beim Auslösen der Fähigkeit die Chance, 'Waffe des Mahlstroms' auszulösen, um 50% erhöht.\n\nErhöht die von 'Erdschild' hervorgerufene Heilung um 25%.\n\nWiederherstellung\nErhöht den von 'Blitzschlagschild' verursachten Schaden um 100%.\n\nErhöht die von 'Erdschild' hervorgerufene Heilung um 25%.\n\nErhöht die Menge an wiederhergestelltem Mana beim Auslösen von 'Wasserschild' um 50%." }
