entries[382109] = { ["name"] = "Geistbeuger", ["text"] = "Ersetzt 'Schattengeist' durch 'Geistbeuger'.\n\n[ Schatten : Geistbeuger\nBeschwört einen Geistbeuger, der das Ziel 15 Sek. lang angreift.\n\nErzeugt jedes Mal, wenn der Geistbeuger angreift, 2 Wahnsinn. /\n\nDisziplin, Heilig\nGeistbeuger\nBeschwört einen Geistbeuger, der das Ziel 12 Sek. lang angreift.\n\nErzeugt jedes Mal, wenn der Geistbeuger angreift, 0.2% Mana. ]" }
