entries[382119] = { ["name"] = "Aufwiegelndes Signollfeuer", ["text"] = "Ca. 1 Procs pro Minute\nEure Fähigkeiten haben eine geringe Chance, einen Gnollverbündeten zu beschwören, der Euch im Kampf unterstützt. Dieser kann Eurem Ziel 3237 körperlichen Schaden zufügen und es für 2 Sek. [verlangsamen][betäuben], Euer Ziel vergiften und ihm so [Quellwert] Naturschaden im Verlauf von 10 Sek. zufügen oder Euren höchsten Sekundärwert für 20 Sek. um 119 erhöhen.", ["unresolvedValues"] = true }
