entries[382126] = { ["name"] = "Machtraub", ["text"] = "Sofort 2 min Abklingzeit\nIhr erzeugt einen Riss in der Zeit und raubt Eurem zukünftigen Ich Macht, um 20 Sek. lang 262 Intelligenz zu erhalten. Ihr verliert danach 83 Intelligenz für 20 Sek." }
