entries[382130] = { ["name"] = "Kristallnetz", ["text"] = "45 Meter Reichweite\nSofort 2 min Abklingzeit\nDurch das Wirken von Zaubern spinnt Ihr 'Kristallseide', die Euch pro Stapel [wenig] Meisterschaft gewährt.\n\nBei X Stapeln verursacht Euer nächster Einzelzielzauber [hohen] zusätzlichen Frostschaden und wickelt Euer Ziel sowie alle Gegner im Umkreis von 10 Metern um das Ziel für X Sek. in ein Kristallnetz ein. Während es besteht, wird ein Teil des von Euch verursachten Schadens auf alle Gegner im Netz aufgeteilt." }
entries[382131] = { ["name"] = "Eisbluttodesfessel", ["text"] = "100 Meter Reichweite\nSofort 2 min Abklingzeit\nDurch das Wirken von Zaubern spinnt Ihr 'Kristallseide', die Euch pro Stapel [wenig] Meisterschaft gewährt.\n\nBei X Stapeln verursacht Euer nächster Einzelzielzauber [hohen] zusätzlichen Frostschaden und wickelt Euer Ziel sowie alle Gegner im Umkreis von 10 Metern um das Ziel für X Sek. in ein Kristallnetz ein. Während es besteht, wird ein Teil des von Euch verursachten Schadens auf alle Gegner im Netz aufgeteilt." }
