entries[382133] = { ["name"] = "Elementarhaltung: Eis", ["text"] = "100 Meter Reichweite\nSofort\nNehmt eine Elementarhaltung ein. Wenn Ihr einem Angriff erfolgreich ausweicht oder ihn pariert, entfesselt Ihr auf Gegner vor Euch einen mächtigen Elementargegenangriff, während Ihr die nächste Haltung einnehmt.\n\nDieser Effekt kann nur einmal alle 30 Sek. auftreten." }
entries[382134] = { ["name"] = "Köder für scheue Kreaturen", ["text"] = "2 Meter ReichweiteWirken in 2 sek. 12 std. Abklingzeit\nPlatziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\nDie Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen auf den Dracheninseln verringert.\n\nKann nur im Freien auf den Dracheninseln verwendet werden." }
