entries[382309] = { ["name"] = "Erwachen der Ahnen", ["text"] = "Wenn Ihr mit 'Welle der Heilung', 'Heilende Woge' oder 'Springflut' heilt, habt Ihr eine Chance von 30%, einen Geist der Ahnen zu beschwören, der Euch unterstützt und sofort ein verbündetes Gruppen- oder Schlachtzugsmitglied innerhalb von 40 Metern um 15% des geheilten Werts heilt. Kritische Treffer erhöhen diese Chance auf 60%." }
