entries[382317] = { ["name"] = "Überentwickelte Ärmelverlängerer", ["text"] = "Wirken in 5 sek. 3\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nSchillernder Wildstoffballen (4), Eingefettete Zahnräder (2), Bogenlichtkondensator (2), Verstärktes Maschinenchassis , Funke (#247)\nOptionale Reagenzien:\nEntdeckung:\nBei der Herstellung von Brillen, Schusswaffen oder Armschienen\nBenötigt:\nSpezialisierung: Funktion übertrifft Form - Zahnrad\n\nÜberentwickelte Ärmelverlängerer\nWird beim Aufheben gebunden\nHandgelenk Stoff\n109 Rüstung\n+144 Intelligenz\n+234 Ausdauer\n+ 269 Zufallswert 1\n\nTüfteleisockel\n\nHaltbarkeit 55 / 55\n58" }
