entries[382321] = { ["name"] = "Alter Qualmer", ["text"] = "Wirken in 5 sek. 3\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nObsidianversengte Legierung (4), Dauerbrennersprengpulver (8), Bogenlichtkondensator (2), Verstärktes Maschinenchassis , Funke (#247) (2)\nOptionale Reagenzien:\nMit Energie erfüllen (#111) , Sekundärwerte anpassen (#125) , Glorreiche Einsicht (#93) , Verzierung hinzufügen (#226) , Ersatzteile (#230)\nBeute von:\nAngriff der Zaqali\nZone:\nAberrus, Schmelztiegel der Schatten\nPläne:\nErhältlich im Auktionshaus\n\nAlter Qualmer\nWird beim Aufheben gebunden\nDistanz Schusswaffe\n406 - 754 Schaden Geschwindigkeit 3.00\n(193.3 Schaden pro Sekunde)\n+257 Beweglichkeit\n+416 Ausdauer\n+ 239 Zufallswert 1\n+ 239 Zufallswert 2\nHaltbarkeit 120 / 120\n58" }
entries[382327] = { ["name"] = "Feuerwerksbündel", ["text"] = "Wirken in 1.5 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nTobendes Feuer (3), Steinkrustenbalg , Dauerbrennersprengpulver (2)\nAngeln:\nDrakonisches Rezept in der Flasche\nPläne:\nErhältlich im Auktionshaus\n\nWird beim Aufheben gebunden\n\"Enthält eine Auswahl von Feuerwerken vieler Zeitalter und Kulturen.\"\n<Zum Öffnen rechtsklicken>" }
entries[382329] = { ["name"] = "Khaz'goritanglerfreund", ["text"] = "Wirken in 3.5 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nKhaz'goriterz (10), Eingefettete Zahnräder (4), Bogenlichtkondensator (2), Verstärktes Maschinenchassis\nOptionale Reagenzien:\nGlorreiche Einsicht (#93) , Ersatzteile (#230)\nBeute von:\nMakelloser Flunkschatzbeutel\nVerkäufer:\nDer Große Flunk\nKosten:\nGoldmünze der Inseln\nBauplan:\nErhältlich im Auktionshaus\n\nKhaz'goritanglerfreund\nWird beim Aufheben gebunden\nWerkzeug für Angeln\n+ 90 Wahrnehmung\nAnlegen: +15 Fertigkeit in Angeln auf den Dracheninseln\nBenötigt Angeln\n(1)" }
entries[382332] = { ["name"] = "Quak-E", ["text"] = "Wirken in 10 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nGeschwungene Vogelfeder (60), Quak-E-Quakmodulator , Malygit (2), Handvoll Serevitbolzen (4), Schockfederspule , Eingefettete Zahnräder (2), Verstärktes Maschinenchassis\nVerkäufer:\nBoss Magor\nZone:\nKüste des Erwachens\nDrachenschuppenexpedition - Ruhmstufe 21\nKosten:\n200\n\nVerkäufer:\nKatalogisiererin Jakes\nZone:\nKüste des Erwachens\nDrachenschuppenexpedition - Ruhmstufe 21\nKosten:\n200\n\nQuak-E\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n1 - 80 ( 80)" }
entries[382335] = { ["name"] = "Grüner Feuerflieger", ["text"] = "Wirken in 1.5 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nAdamantschuppen , Dauerbrennersprengpulver (2)\nVerkäufer:\nRabul\nZone:\nValdrakken\nHandwerkerkonsortium - Hochverehrt\nKosten:\n200\n\nBenutzen: Schießt ein Feuerwerk zu Ehren des grünen Drachenschwarms ab." }
entries[382336] = { ["name"] = "H.I.L.F.E.", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nErweckte Zorneskraft (3), Ehrenabzeichen (15), Handvoll Serevitbolzen (6), Dauerbrennersprengpulver (4), Verstärktes Maschinenchassis\nVerkäufer:\nEraneth\nZone:\nValdrakken\nKosten:\n3\n\nH.I.L.F.E.\nWird beim Aufheben gebunden\nSpielzeug\nBenutzen: Verschießt ein Signalleuchtfeuer, um Verbündete in der Nähe vor drohender Gefahr zu warnen.\n\nKann nur auf Schlachtfeldern verwendet werden. In einem Bereich kann von derselben Fraktion nur einmal alle 3 Min. ein Signalleuchtfeuer verschossen werden. (2 Min Abklingzeit)\n\"Hallo Ihr, lebe für Errettung!\"" }
entries[382337] = { ["name"] = "Tragbare Werkbank des Tüftlers", ["text"] = "Wirken in 5 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nRahmenlose Linse , Handvoll Serevitbolzen (2), Schockfederspule , Eingefettete Zahnräder\nVerkäufer:\nRabul\nZone:\nValdrakken\nHandwerkerkonsortium - Respektiert\nKosten:\n75\n\nTragbare Werkbank des Tüftlers\nBenutzen: Stellt eine tragbare Werkbank des Tüftlers auf, an dem Ingenieure in der Nähe 5*2 Min. lang ihrem Handwerk nachgehen können.\n\nWahrscheinlich wird sie nicht explodieren. (5 Min Abklingzeit)" }
