entries[382367] = { ["name"] = "Wyrmlochgenerator: Dracheninseln", ["text"] = "Wirken in 10 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nErweckte Ordnung (3), Handvoll Serevitbolzen (2), Schockfederspule , Eingefettete Zahnräder (2), Bogenlichtkondensator (3), Verstärktes Maschinenchassis\nSpezialisierung:\nMechanischer Verstand\n\nWyrmlochgenerator: Dracheninseln\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Öffnet ein Wurmloch, das es dem Benutzer ermöglicht, schnell an einen zufälligen Ort auf den Dracheninseln zu reisen.\n\nIngenieure, die sich auf Triangulation spezialisieren, können lernen, wie man an bestimmte Orte gelangt. (30 Min Abklingzeit)\nBenötigt Ingenieurskunst der Dracheninseln\n(1)" }
entries[382368] = { ["name"] = "Zentraler Niederschlagsauslöser", ["text"] = "Wirken in 10 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nFrostige Seele (3), Luftige Seele (3), Elementarharmonie , Handvoll Serevitbolzen (20), Schockfederspule (3), Bogenlichtkondensator (4), Verstärktes Maschinenchassis\nSpezialisierung:\nMechanischer Verstand - Neuheiten (5)\n\nZentraler Niederschlagsauslöser\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Platziert einen zentralen Niederschlagsauslöser für bis zu 2 Stunden, mit dem Ihr freiwillig den Zorn der Natur erleben könnt!\n\nEin integrierter Tarnmechanismus sorgt dafür, dass nur Mitglieder Eurer Gruppe oder Eures Schlachtzugs das Gerät und seine Effekte sehen können.\n\nKann nur im Freien verwendet werden. (2 Std. Abklingzeit)" }
