entries[382404] = { ["name"] = "Roter Feuerflieger", ["text"] = "Wirken in 1.5 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nWiderstandsfähiges Leder , Dauerbrennersprengpulver (2)\nVerkäufer:\nRabul\nZone:\nValdrakken\nHandwerkerkonsortium - Bevorzugt\nKosten:\n200\n\nBenutzen: Schießt ein Feuerwerk zu Ehren des roten Drachenschwarms ab." }
entries[382405] = { ["name"] = "Drakonische Schießschuhe", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nP.E.N.G. x2 , Dauerbrennersprengpulver\nOptionale Reagenzien:\nGeringe glorreiche Einsicht (#92)" }
entries[382407] = { ["name"] = "Neuraler Stummschalter Mk. 3", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nWildstoff , Handvoll Serevitbolzen (4), Schockfederspule (2), Eingefettete Zahnräder\nBerufsausbilder:\nIngenieurskunst der Dracheninseln (15)\nKosten:\n50\n\nBenutzen: Macht Euch immun gegen manche Ärgernisse. Bleibt über den Tod hinaus bestehen. Hält 12 Stunden lang an.\n58" }
entries[382408] = { ["name"] = "Atomarer Rekalibrierer", ["text"] = "Wirken in 3.5 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHandvoll Serevitbolzen (20), Schockfederspule (6), Eingefettete Zahnräder (4), Bogenlichtkondensator (2), Verstärktes Maschinenchassis (2)\nSpezialisierung:\nMechanischer Verstand - Neuheiten (10)\n\nAtomarer Rekalibrierer\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Setzt ein Gerät ein, das vorübergehend die genetische Zusammensetzung von jedem verändert, den Ihr dazu bringt, sich draufzustellen. (12 Std. Abklingzeit)" }
entries[382410] = { ["name"] = "Welkblitz", ["text"] = "60 Meter Reichweite\nWirken in 3 sek.\nDie von der Verfallmagie eines Totems in der Nähe erfüllte Mystikerin der Trickklauen feuert einen ausdörrenden Blitz ab, der 3394229 Naturschaden verursacht und ' Siechen ' anwendet." }
entries[382411] = { ["name"] = "Ewigkeitswoge", ["text"] = "25 Meter Reichweite\nKanalisiert (Wirken in 3.25 sek.) 30 sek. Abklingzeit\nKonzentriert Eure Energien und setzt eine Salve purer Magie frei, die einem Gegner [(818.4% der Zaubermacht)] Zauberfrostschaden zufügt. Fügt bei Ermächtigung zusätzlichen Gegnern innerhalb von 25 Metern Schaden zu.\n\nI: Fügt [ Spanne der Ewigkeit : 2 Gegnern Gegner] Schaden zu.\n\nII: Fügt [ Spanne der Ewigkeit : 4 Gegnern / 2 Gegnern] Schaden zu.\n\nIII: Fügt [ Spanne der Ewigkeit : 6 Gegnern / 3 Gegnern] Schaden zu.\n\nIV: Fügt [ Spanne der Ewigkeit : 8 Gegnern / 4 Gegnern] Schaden zu." }
entries[382412] = { ["name"] = "Welkblitz", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie von der Verfallmagie eines Totems in der Nähe erfüllte Mystikerin der Trickklauen feuert einen ausdörrenden Blitz ab, der 3394229 Naturschaden verursacht und ' Siechen ' anwendet." }
entries[382414] = { ["name"] = "Aufkommendes Frösteln", ["text"] = "Wirken in 3 sek.\nReagenzien:\nFrost-Ass , Frost-Zwei , Frost-Drei , Frost-Vier , Frost-Fünf , Frost-Sechs , Frost-Sieben , Frost-Acht\nVereint alle Karten vom Ass bis zur Acht des Frosts, um das Set zu vervollständigen." }
entries[382415] = { ["name"] = "Erfrischender Tanz", ["text"] = "Wirken in 3 sek.\nReagenzien:\nLuft-Ass , Luft-Zwei , Luft-Drei , Luft-Vier , Luft-Fünf , Luft-Sechs , Luft-Sieben , Luft-Acht\nVereint alle Karten vom Ass bis zur Acht der Luft, um das Set zu vervollständigen." }
entries[382416] = { ["name"] = "Behüter", ["text"] = "Wirken in 3 sek.\nReagenzien:\nErd-Ass , Erd-Zwei , Erd-Drei , Erd-Vier , Erd-Fünf , Erd-Sechs , Erd-Sieben , Erd-Acht\nVereint alle Karten vom Ass bis zur Acht der Erde, um das Set zu vervollständigen." }
entries[382417] = { ["name"] = "Verzweifelte Herbeirufung", ["text"] = "45 Meter Reichweite\nSofort 20 sek. Abklingzeit\nEntfesselt gefährliche Blitze und fügt Eurem Ziel 5877 Naturschaden und Euch 31 Schaden zu. Der Euch selbst zugefügte Schaden wird durch Stapel von Hass erhöht." }
