entries[383059] = { ["name"] = "Winde der Veränderung", ["text"] = "100 Meter Reichweite\nSofort\nErkhart beschwört einen örtlich begrenzten Hurrikan, der 5 Sek. lang alle 1 Sek. 242445 Naturschaden verursacht und Spielercharaktere sowie Kyrakkas ' Flammende Glut ' in eine Richtung stößt." }
