entries[383061] = { ["name"] = "Magmaeruption", ["text"] = "100 Meter Reichweite\nSofort\nBeschwört ein Totem am Zielort, das sich entlädt und 3 Gegnern innerhalb von 8 Metern (99.099% der Zaubermacht) Feuerschaden zufügt und sie mit 'Flammenschock' belegt. Schleudert 6 Sek. lang alle 1 Sek. flüssiges Magma nach einem zufälligen Ziel in der Nähe und fügt allen Gegnern innerhalb von 8 Metern [(54.5044% der Zaubermacht) * 1.1] Feuerschaden zu.\n\nElementar\nGenerates 8 Maelstrom." }
entries[383062] = { ["name"] = "Peitscher beschwören", ["text"] = "30 Meter Reichweite\nWirken in 3 sek.\nBeschwört einen infizierten Peitscher, der dem Kampf beitritt." }
entries[383063] = { ["name"] = "Wachsenden Vorrat an drakonischen Delikatessen herrichten", ["text"] = "5 Meter Reichweite\nWirken in 1 sek.\nRichtet einen wachsenden Vorrat an drakonischen Delikatessen her, der mit köstlichen zubereiteten Mahlzeiten sowie überschüssigen Zutaten bestückt werden kann. Stellt das Festmahl fertig, damit alle es genießen können!\n\nDas fertige Festmahl stellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und Euer Primärwert wird 1 Stunde lang um 76 erhöht." }
