entries[383073] = { ["name"] = "Zerschmetternder Einschlag", ["text"] = "Unbegrenzte Reichweite\nWirken in 3 sek.\nTerros lässt die Erde aufbrechen. Fügt Spielercharakteren innerhalb von 12 Metern um den Einschlag 529971 Naturschaden zu und schleudert sie in die Luft.\n\n' Gesprungener Schutt ' fällt von der Decke herab." }
