entries[383082] = { ["name"] = "Barbarentraining", ["text"] = "Schutz\n'Rache' verursacht 20% mehr Schaden. 'Donnerknall' verursacht 10% mehr Schaden.\n\nFuror\n'Zerschmettern' und 'Wirbelwind' verursachen 20% mehr Schaden und 10% mehr kritischen Schaden.\n\nFuror (Grollender Donner)\n'Zerschmettern', 'Donnerknall' und 'Wirbelwind' verursachen 20% mehr Schaden und 10% mehr kritischen Schaden.\n\nWaffen\n'Zerschmettern', 'Spalten' und 'Wirbelwind' verursachen 10% mehr Schaden und 10% mehr kritischen Schaden." }
