entries[383404] = { ["name"] = "Leben entfesseln", ["text"] = "100 Meter Reichweite\nSofort\nEntfesselt die Elementarkräfte des Lebens und heilt ein verbündetes Ziel um (319.2% der Zaubermacht) Gesundheit. Zusätzlich wird Euer nächster Heilzauber effektiver.\n\n'Springflut', 'Welle der Heilung' oder 'Heilende Woge' : Heilung um 35% erhöht.\n\n'Kettenheilung' : Heilung um 15% erhöht und springt auf 1 zusätzliches Ziel über.\n\n'Heilender Regen' oder 'Platzregen' : Wirkt sich auf 2 zusätzliche Ziele aus.\n\n'Lebensquell' : 40% der überschüssigen Heilung werden in einen Absorptionseffekt umgewandelt." }
