entries[383512] = { ["name"] = "Kartenbündel: Dracheninseln", ["text"] = "Wirken in 3.5 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nErweckte Ordnung (3), Erweckte Luft (3), Erweckte Erde (3), Erwecktes Feuer (3), Erweckter Frost (3), Glitzerndes Pergament (3)\nSpezialisierung:\nArchivieren - Dunkelmondgeheimnisse\n\nKartenbündel: Dracheninseln\nBenutzen: Aufreißen, um Dunkelmondkarten zu erhalten! Enthält nur Karten, die von den Dracheninseln stammen.\nHandwerksmaterial" }
