entries[383515] = { ["name"] = "Drakonische Kräuterkundeabhandlung", ["text"] = "Wirken in 3.5 sek. 2\nReagenzien:\nEifer des Handwerkers (10), Felszahnleder , Glitzerndes Pergament (5), Erweckte Erde , Brünierte Tinte\nEntdeckung:\nBei der Herstellung anderer drakonischer Abhandlungen\nBenötigt:\nSpezialisierung: Archivieren - Drakonische Abhandlungen\n\nDrakonische Kräuterkundeabhandlung\nWird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Kräuterkundewissen der Dracheninseln um 1 zu erhöhen.\nBenötigt Kräuterkunde der Dracheninseln\n(25)\n\"Enthält Notizen über verschiedene Berufsgeheimnisse von Kräuterkundigen. Kann nur einmal pro Woche gelesen werden.\"" }
